#[cfg(test)]
mod tests {
    #![allow(unused_imports)]
    use super::*;
    use crate::field::FieldValue;
    use crate::packet::Packet;

    // protogen:tests begin
    /// RFC 5905 §7.3 client packet: version 4, mode 3 (client), stratum 0, poll 6, all timestamps zero.
    fn vector() -> Vec<u8> {
        vec![
            0x23, 0x00, 0x06, 0xec, 0x00, 0x00, 0x00, 0x00, 0x00, 0x00, 0x00, 0x00, 0x00, 0x00,
            0x00, 0x00, 0x00, 0x00, 0x00, 0x00, 0x00, 0x00, 0x00, 0x00, 0x00, 0x00, 0x00, 0x00,
            0x00, 0x00, 0x00, 0x00, 0x00, 0x00, 0x00, 0x00, 0x00, 0x00, 0x00, 0x00, 0x00, 0x00,
            0x00, 0x00, 0x00, 0x00, 0x00, 0x00,
        ]
    }

    #[test]
    fn dissects_the_rfc_vector() {
        let p = Packet::dissect(vector(), ProtoId::Ntp);
        let l = p.find_layer(ProtoId::Ntp).unwrap();
        assert_eq!(p.get(l, "leap").unwrap(), FieldValue::Uint(0));
        assert_eq!(p.get(l, "version").unwrap(), FieldValue::Uint(4));
        assert_eq!(p.get(l, "mode").unwrap(), FieldValue::Uint(3));
        assert_eq!(p.get(l, "stratum").unwrap(), FieldValue::Uint(0));
        assert_eq!(p.get(l, "poll").unwrap(), FieldValue::Uint(6));
        assert_eq!(p.get(l, "precision").unwrap(), FieldValue::Uint(236));
        assert_eq!(p.get(l, "delay").unwrap(), FieldValue::Uint(0));
        assert_eq!(p.get(l, "dispersion").unwrap(), FieldValue::Uint(0));
        assert_eq!(p.get(l, "id").unwrap(), FieldValue::Uint(0));
        assert_eq!(p.raw_bytes(), &vector()[..]);
    }

    #[test]
    fn truncation_does_not_panic() {
        for n in 0..vector().len() {
            let p = Packet::dissect(vector()[..n].to_vec(), ProtoId::Ntp);
            assert_eq!(p.raw_bytes(), &vector()[..n]);
        }
    }

    #[test]
    fn writes_survive_a_rebuild() {
        let mut p = Packet::dissect(vector(), ProtoId::Ntp);
        let l = p.find_layer(ProtoId::Ntp).unwrap();
        let n = p.raw_bytes().len();
        for f in crate::proto::active_fields(ProtoId::Ntp, p.header(l))
            .filter(|f| f.kind == crate::field::FieldKind::Uint && f.bit_len <= 32)
            .map(|f| f.name)
            .collect::<Vec<_>>()
        {
            p.set_uint(l, f, 1);
        }
        assert_eq!(p.to_bytes().len(), n);
    }
    // protogen:tests end
}
